Your expense tracker is below. Add each spend with a note, amount, category and date, set a monthly budget, and it shows what's left and where the money went. It saves on this device when the app allows it.

```page
<!doctype html>
<html><head><meta charset="utf-8">
<style>
*{box-sizing:border-box}
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#f6f7f4;color:#1f2a24}
h2{margin:0 0 10px;font-size:18px}
.card{background:#fff;border-radius:12px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select{padding:8px;border:1px solid #cfd6cf;border-radius:8px;font-size:14px;flex:1;min-width:110px}
button{padding:8px 14px;border:0;border-radius:8px;background:#2f7d57;color:#fff;font-size:14px;cursor:pointer}
button.x{background:#fff;color:#b3261e;padding:4px 8px;font-size:16px}
.big{font-size:24px;font-weight:600}
.muted{color:#69746d;font-size:13px}
.bar{height:10px;background:#e6ebe6;border-radius:6px;overflow:hidden;margin:4px 0 10px}
.fill{height:100%;background:#2f7d57}
.over{background:#b3261e}
.item{display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid #eef1ee}
.item:last-child{border:0}
.cat{display:flex;justify-content:space-between;font-size:14px}
</style></head><body>

<div class="card">
  <h2>This month</h2>
  <div class="row">
    <input type="month" id="month">
    <input type="number" id="budget" placeholder="Monthly budget (₹)" min="0">
  </div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left"></div>
  <div class="bar"><div class="fill" id="bf" style="width:0"></div></div>
</div>

<div class="card">
  <h2>Add an expense</h2>
  <div class="row">
    <input id="desc" placeholder="What was it for?">
    <input type="number" id="amt" placeholder="Amount (₹)" min="0">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option>
      <option>Fun</option><option>Other</option>
    </select>
    <input type="date" id="date">
    <button id="add">Add</button>
  </div>
  <div class="muted" id="msg"></div>
</div>

<div class="card">
  <h2>Where it went</h2>
  <div id="cats" class="muted">Nothing yet.</div>
</div>

<div class="card">
  <h2>All expenses</h2>
  <div id="list" class="muted">Nothing yet.</div>
</div>

<script>
var KEY="foo_expenses_v1", data={items:[],budget:0};
try{var s=localStorage.getItem(KEY);if(s)data=JSON.parse(s);}catch(e){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch(e){}}
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN");}
var $=function(i){return document.getElementById(i)};
var now=new Date();
function pad(n){return String(n).padStart(2,"0")}
$("date").value=now.getFullYear()+"-"+pad(now.getMonth()+1)+"-"+pad(now.getDate());
$("month").value=now.getFullYear()+"-"+pad(now.getMonth()+1);
$("budget").value=data.budget||"";

function render(){
  var m=$("month").value;
  var items=data.items.filter(function(x){return x.date.slice(0,7)===m})
    .sort(function(a,b){return a.date<b.date?1:-1});
  var total=items.reduce(function(a,x){return a+x.amt},0);
  $("total").textContent=inr(total)+" spent";
  var b=Number(data.budget)||0, bf=$("bf");
  if(b>0){
    var diff=b-total;
    $("left").textContent=diff>=0?inr(diff)+" left of "+inr(b):inr(-diff)+" over your budget of "+inr(b);
    bf.style.width=Math.min(100,total/b*100)+"%";
    bf.className="fill"+(diff<0?" over":"");
  }else{$("left").textContent="Set a budget to see what's left.";bf.style.width="0";}

  var by={};items.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var cats=$("cats");cats.innerHTML="";
  var keys=Object.keys(by).sort(function(a,c){return by[c]-by[a]});
  if(!keys.length){cats.textContent="Nothing yet.";}
  keys.forEach(function(k){
    var w=document.createElement("div");
    var r=document.createElement("div");r.className="cat";
    var a=document.createElement("span");a.textContent=k;
    var c=document.createElement("span");c.textContent=inr(by[k])+" ("+Math.round(by[k]/total*100)+"%)";
    r.appendChild(a);r.appendChild(c);
    var bar=document.createElement("div");bar.className="bar";
    var f=document.createElement("div");f.className="fill";f.style.width=(by[k]/total*100)+"%";
    bar.appendChild(f);w.appendChild(r);w.appendChild(bar);cats.appendChild(w);
  });

  var list=$("list");list.innerHTML="";
  if(!items.length){list.textContent="Nothing yet.";}
  items.forEach(function(x){
    var row=document.createElement("div");row.className="item";
    var l=document.createElement("div");
    var t=document.createElement("div");t.textContent=x.desc||x.cat;
    var d=document.createElement("div");d.className="muted";d.textContent=x.cat+" · "+x.date;
    l.appendChild(t);l.appendChild(d);
    var r=document.createElement("div");
    var p=document.createElement("span");p.textContent=inr(x.amt)+" ";
    var del=document.createElement("button");del.className="x";del.textContent="✕";
    del.onclick=function(){data.items=data.items.filter(function(y){return y.id!==x.id});save();render();};
    r.appendChild(p);r.appendChild(del);
    row.appendChild(l);row.appendChild(r);list.appendChild(row);
  });
}

$("add").onclick=function(){
  var amt=Number($("amt").value);
  if(!(amt>0)){$("msg").textContent="Enter an amount above zero.";return;}
  if(!$("date").value){$("msg").textContent="Pick a date.";return;}
  data.items.push({id:Date.now()+Math.random(),desc:$("desc").value.trim(),amt:amt,cat:$("cat").value,date:$("date").value});
  $("desc").value="";$("amt").value="";$("msg").textContent="Added.";
  $("month").value=$("date").value.slice(0,7);
  save();render();
};
$("budget").oninput=function(){data.budget=Number($("budget").value)||0;save();render();};
$("month").onchange=render;
render();
</script>
</body></html>
```
